-- Store.Enqueue: one new queued row, on the caller's transaction (Send; SendTo). Call once per
-- recipient. Use Query (RETURNING).
-- Args: $1 id uuid (MessageID, generated by the caller), $2 owner text, $3 template text,
-- $4 key text (NULL: no idempotency key), $5 person_id uuid (NULL for SendTo),
-- $6 address text (NULL unless SendTo), $7 language text (the tag rendered), $8 subject text,
-- $9 body text, $10 now timestamptz (the service clock: becomes created_at and
-- next_attempt_at), $11 expires_at timestamptz (now + the message TTL, at most MaxAge; must be
-- after $10).
-- Columns, in order: id uuid. ZERO rows means the message is a duplicate and was skipped
-- silently (F13), nothing counted: a row for (owner, key, person_id) exists
-- (notify_message_owner_key_person_uidx), or, for SendTo, a live row for (owner, key, address)
-- exists (notify_message_owner_key_address_uidx). A SendTo row never conflicts on the person
-- index (person_id is NULL); one with another address, or whose address was already cleared,
-- inserts. The conflict clause names no target, because Postgres allows one target and there
-- are two indexes; the price is that a primary-key collision (a duplicate random ID) is also
-- skipped rather than reported.
-- Constraint errors (*db.Error.Constraint, all Invalid; Send validates first, so each is a
-- caller bug except subject_chk and body_chk, the F12 rendered-too-long and control-character
-- cases): notify_message_person_id_fkey (no such person), notify_message_nil_uuid_chk,
-- notify_message_owner_chk, notify_message_template_chk, notify_message_key_chk,
-- notify_message_address_chk, notify_message_language_chk, notify_message_subject_chk,
-- notify_message_body_chk, notify_message_recipient_chk, notify_message_live_chk,
-- notify_message_text_chk, notify_message_expires_chk (expires_at not after created_at).
INSERT INTO core.notify_message
    (id, owner, template, key, person_id, address, language, subject, body,
     status, attempts, next_attempt_at, created_at, expires_at)
VALUES
    ($1::uuid, $2::text, $3::text, $4::text, $5::uuid, $6::text, $7::text, $8::text, $9::text,
     'queued', 0, $10::timestamptz, $10::timestamptz, $11::timestamptz)
ON CONFLICT DO NOTHING
RETURNING id
